(lib.HitArea = function(mode,startPosition,loop) {
	this.initialize(mode,startPosition,loop,{});

	// timeline functions:
	this.frame_0 = function() {
		this.stop();
		
		this.on('click', function (e){
		if (testbtn == false) {
		if (cs==true) {
		if (this.currentFrame==1) {
		
		//Проверяем - был ли дан ответ
		if (ca[cm[1]]==0) {
			
		//рисуем линию
		var line = new createjs.Shape();
		line.name = 'line0' + String(cm[1] + this.name.charAt(2));
		line.graphics.setStrokeStyle(3);
		line.graphics.beginStroke("#334BCF");
		line.graphics.moveTo(cardc[cm[1]].x+105, cardc[cm[1]].y).lineTo(this.x-85, this.y);
		
		//записываем ответ в массив
		ca[cm[1]]=this.name.charAt(2);
		//добавляем линию в массив 	
		lines[cm[1]]=line;
		//добавляем линию на сцену
		this.parent.addChild(line);	
		//переход на фрейм "выбрано"
		cardnames[cm[1]].gotoAndStop(2);
		
		this.gotoAndStop(2);
		
		for (i=1; i<5; i++) {
			if (cardc[i].ldot.visible == false) {
		cardc[i].cursor = "pointer";
		cardc[i].buttonMode = true;	
		}
		if (cards[i].currentFrame == 1) {
			cards[i].gotoAndStop(0);
		//отключаем реакцию курсора мыши над картами
		cards[i].cursor = "default";
		cards[i].buttonMode = false;
			}else{
			continue;
		}
		}
		
		//снимаем блокировку выбора других названий	
		bl=0;
				
		}else{
			return;
		}
		}
		}else{
			return;
		}
		}
		});
	}
	this.frame_1 = function() {
		this.cursor = "pointer";
		this.buttonMode = true;
	}
	this.frame_2 = function() {
		//отключаем реакцию курсора мыши
		this.cursor = "default";
		this.buttonMode = false;
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1).call(this.frame_1).wait(1).call(this.frame_2).wait(1));

	// bluedot
	this.ldot = new lib.Linkdot();
	this.ldot.name = "ldot";
	this.ldot.parent = this;
	this.ldot.setTransform(-5,4.9,1,1,0,0,0,0,0.5);
	this.ldot._off = true;

	this.timeline.addTween(cjs.Tween.get(this.ldot).wait(1).to({_off:false},0).wait(2));

	// layer
	this.shape = new cjs.Shape();
	this.shape.graphics.f("rgba(0,0,255,0.008)").s().p("AtHBkIAAjHIaPAAIAADHg");
	this.shape.setTransform(84,10);

	this.timeline.addTween(cjs.Tween.get(this.shape).wait(3));

}).prototype = p = new cjs.MovieClip();
p.nominalBounds = new cjs.Rectangle(-5,0,173,20);


